SELECT participant_id FROM public.health_examination_session_assignments
WHERE session_id=#{sessionId} AND status IN ('ASSIGNED','ATTENDED') AND participant_id IN
#{id}

SELECT  FROM public.health_examination_session_assignments
WHERE organization_id=#{organizationId} AND session_id=#{sessionId} AND status=#{status}
ORDER BY id FOR UPDATE

mapper.sql:
a.organization_id=#{organizationId} AND a.session_id=#{sessionId}
AND a.status=#{status}
AND (LOWER(p.full_name) LIKE #{pattern} ESCAPE chr(92) OR
    LOWER(COALESCE(p.participant_code,'')) LIKE #{pattern} ESCAPE chr(92)
    OR LOWER(p.department_name) LIKE #{pattern} ESCAPE chr(92))

mapper.select:
SELECT a.id AS assignment_id,a.status,a.attended_at,a.note,a.row_version AS assignment_row_version, p.id AS participant_id,p.agreement_id,p.participant_code,p.full_name,p.date_of_birth,p.sex, p.identification_number,p.department_name,p.position_name,p.roster_status FROM public.health_examination_session_assignments a JOIN public.health_examination_participants p ON p.id=a.participant_id WHERE ORDER BY
p.full_name DESC, a.id ASC p.full_name ASC, a.id ASC p.participant_code DESC NULLS LAST, a.id ASC p.participant_code ASC NULLS LAST, a.id ASC p.department_name DESC, a.id ASC p.department_name ASC, a.id ASC a.status DESC, a.id ASC a.status ASC, a.id ASC a.id DESC a.id ASC
LIMIT #{limit} OFFSET #{offset}
